// A 200 from the API does not mean we got what we asked for.
// Validate defensively, then derive the routing decision.
const response = $input.first().json;
const upstream = $('Validate Payload').first().json;

if (response.stop_reason === 'refusal') {
  throw new Error('Model declined the request: ' + (response.stop_details?.category ?? 'unknown'));
}

const toolUse = (response.content ?? []).find(
  (block) => block.type === 'tool_use' && block.name === 'record_quote_request',
);
if (!toolUse) throw new Error('No record_quote_request tool_use block in response');

const extracted = toolUse.input;

// Routing thresholds live here, not in the prompt. Business rules belong in code
// where they can be diffed, tested, and changed without re-evaluating a model.
const HIGH_VALUE_AUD = 15000;
const MIN_CONFIDENCE = 0.75;

const reasons = [];
if (extracted.estimated_value_aud >= HIGH_VALUE_AUD) {
  reasons.push('ballpark >= ' + HIGH_VALUE_AUD + ' AUD');
}
if (extracted.confidence < MIN_CONFIDENCE) {
  reasons.push('extraction confidence ' + extracted.confidence);
}
if (extracted.urgency === 'emergency') reasons.push('flagged as emergency');
if (extracted.missing_information.length > 2) reasons.push('too many open questions');

return [{
  json: {
    ...upstream,
    extracted,
    needsApproval: reasons.length > 0,
    approvalReasons: reasons,
    usage: response.usage,
    modelServed: response.model,
  },
}];

